mapper.select:
SELECT COUNT(1) FROM mail_message m INNER JOIN mail_recipient r ON r.mail_id = m.id INNER JOIN sys_user sender ON sender.id = m.sender_id WHERE r.recipient_id = #{userId} AND r.deleted_flag = 1
AND ( m.subject LIKE CONCAT('%', #{keyword}, '%') OR m.content LIKE CONCAT('%', #{keyword}, '%') OR sender.username LIKE CONCAT('%', #{keyword}, '%') OR sender.nickname LIKE CONCAT('%', #{keyword}, '%') )
AND m.sent_at >= #{startTime}
AND m.sent_at <= #{endTime}

SELECT m.id AS mail_id, COALESCE(m.thread_id, m.id) AS thread_id, m.reply_to_mail_id, m.subject, m.content, sender.username AS sender_username, sender.nickname AS sender_nickname, recipient.username AS recipient_username, recipient.nickname AS recipient_nickname, m.sent_at, r.read_flag, r.deleted_flag, r.deleted_at, COALESCE(a.priority, 'MEDIUM') AS priority, COALESCE(a.spam_flag, r.spam_flag, 0) AS spam_flag, COALESCE(a.spam_level, r.spam_level, 'NONE') AS spam_level, COALESCE(a.risk_level, r.risk_level, 'SAFE') AS risk_level, a.risk_reason, COALESCE(a.analysis_status, 'NOT_STARTED') AS analysis_status FROM mail_message m INNER JOIN mail_recipient r ON r.mail_id = m.id INNER JOIN sys_user sender ON sender.id = m.sender_id INNER JOIN sys_user recipient ON recipient.id = r.recipient_id LEFT JOIN mail_analysis a ON a.mail_id = m.id AND a.recipient_id = r.recipient_id WHERE r.recipient_id = #{userId} AND r.deleted_flag = 1
AND ( m.subject LIKE CONCAT('%', #{keyword}, '%') OR m.content LIKE CONCAT('%', #{keyword}, '%') OR sender.username LIKE CONCAT('%', #{keyword}, '%') OR sender.nickname LIKE CONCAT('%', #{keyword}, '%') )
AND m.sent_at >= #{startTime}
AND m.sent_at <= #{endTime}
ORDER BY r.deleted_at DESC, m.sent_at DESC LIMIT #{size} OFFSET #{offset}

SELECT COUNT(1)
FROM mail_message m
INNER JOIN mail_recipient r ON r.mail_id = m.id
LEFT JOIN mail_analysis a ON a.mail_id = m.id AND a.recipient_id = r.recipient_id
WHERE r.recipient_id = #{userId}
  AND r.deleted_flag = 0
  AND (COALESCE(a.spam_flag, r.spam_flag, 0) = 1 OR COALESCE(a.risk_level, r.risk_level, 'SAFE') IN ('MEDIUM', 'HIGH'))

  AND COALESCE(a.spam_level, r.spam_level, 'NONE') = #{spamLevel}


  AND COALESCE(a.risk_level, r.risk_level, 'SAFE') = #{riskLevel}

SELECT m.id AS mail_id, COALESCE(m.thread_id, m.id) AS thread_id, m.reply_to_mail_id, m.subject, m.content, sender.username AS sender_username, sender.nickname AS sender_nickname, recipient.username AS recipient_username, recipient.nickname AS recipient_nickname, m.sent_at, r.read_flag, r.deleted_flag, r.deleted_at, COALESCE(a.priority, 'MEDIUM') AS priority, COALESCE(a.spam_flag, r.spam_flag, 0) AS spam_flag, COALESCE(a.spam_level, r.spam_level, 'NONE') AS spam_level, COALESCE(a.risk_level, r.risk_level, 'SAFE') AS risk_level, a.risk_reason, COALESCE(a.analysis_status, 'NOT_STARTED') AS analysis_status FROM mail_message m INNER JOIN mail_recipient r ON r.mail_id = m.id INNER JOIN sys_user sender ON sender.id = m.sender_id INNER JOIN sys_user recipient ON recipient.id = r.recipient_id LEFT JOIN mail_analysis a ON a.mail_id = m.id AND a.recipient_id = r.recipient_id WHERE r.recipient_id = #{userId} AND r.deleted_flag = 0 AND (COALESCE(a.spam_flag, r.spam_flag, 0) = 1 OR COALESCE(a.risk_level, r.risk_level, 'SAFE') IN ('MEDIUM', 'HIGH'))
AND COALESCE(a.spam_level, r.spam_level, 'NONE') = #{spamLevel}
AND COALESCE(a.risk_level, r.risk_level, 'SAFE') = #{riskLevel}
ORDER BY m.sent_at DESC LIMIT #{size} OFFSET #{offset}

SELECT COUNT(1)
FROM mail_message m
LEFT JOIN mail_recipient r ON r.mail_id = m.id AND r.recipient_id = #{userId}
WHERE m.id = #{mailId}
  AND (m.sender_id = #{userId} OR r.id IS NOT NULL)

SELECT COUNT(1)
FROM (
    SELECT COALESCE(m.thread_id, m.id) AS thread_id
    FROM mail_message m
    INNER JOIN mail_recipient r ON r.mail_id = m.id
    INNER JOIN sys_user sender ON sender.id = m.sender_id
    LEFT JOIN mail_analysis a ON a.mail_id = m.id AND a.recipient_id = r.recipient_id
    WHERE (m.sender_id = #{userId} OR r.recipient_id = #{userId})

      AND (
        m.subject LIKE CONCAT('%', #{keyword}, '%')
        OR m.content LIKE CONCAT('%', #{keyword}, '%')
        OR sender.username LIKE CONCAT('%', #{keyword}, '%')
        OR sender.nickname LIKE CONCAT('%', #{keyword}, '%')
      )


      AND r.recipient_id = #{userId}
      AND r.read_flag = 0


      AND (m.sender_id = #{userId} OR r.read_flag = 1)


      AND sender.username = #{senderUsername}


      AND a.priority = #{priority}


      AND m.sent_at >= #{startTime}


      AND m.sent_at <= #{endTime}

    GROUP BY COALESCE(m.thread_id, m.id)
) t

SELECT base.thread_id, last_mail.subject, last_mail.id AS last_mail_id, last_mail.content AS last_content, last_sender.username AS last_sender_username, last_sender.nickname AS last_sender_nickname, last_recipient_user.username AS last_recipient_username, last_recipient_user.nickname AS last_recipient_nickname, last_mail.sent_at AS last_sent_at, base.unread_count, base.mail_count, base.updated_at, COALESCE(last_analysis.priority, 'MEDIUM') AS priority, COALESCE(last_analysis.spam_flag, last_recipient.spam_flag, 0) AS spam_flag, COALESCE(last_analysis.spam_level, last_recipient.spam_level, 'NONE') AS spam_level, COALESCE(last_analysis.risk_level, last_recipient.risk_level, 'SAFE') AS risk_level, last_analysis.risk_reason, COALESCE(last_analysis.analysis_status, 'NOT_STARTED') AS analysis_status FROM ( SELECT COALESCE(m.thread_id, m.id) AS thread_id, SUM(CASE WHEN r.recipient_id = #{userId} AND r.read_flag = 0 THEN 1 ELSE 0 END) AS unread_count, COUNT(1) AS mail_count, MAX(m.sent_at) AS updated_at FROM mail_message m INNER JOIN mail_recipient r ON r.mail_id = m.id INNER JOIN sys_user sender ON sender.id = m.sender_id LEFT JOIN mail_analysis a ON a.mail_id = m.id AND a.recipient_id = r.recipient_id WHERE (m.sender_id = #{userId} OR r.recipient_id = #{userId})
AND ( m.subject LIKE CONCAT('%', #{keyword}, '%') OR m.content LIKE CONCAT('%', #{keyword}, '%') OR sender.username LIKE CONCAT('%', #{keyword}, '%') OR sender.nickname LIKE CONCAT('%', #{keyword}, '%') )
AND r.recipient_id = #{userId} AND r.read_flag = 0
AND (m.sender_id = #{userId} OR r.read_flag = 1)
AND sender.username = #{senderUsername}
AND a.priority = #{priority}
AND m.sent_at >= #{startTime}
AND m.sent_at <= #{endTime}
GROUP BY COALESCE(m.thread_id, m.id) ) base INNER JOIN mail_message last_mail ON last_mail.id = ( SELECT m2.id FROM mail_message m2 INNER JOIN mail_recipient r2 ON r2.mail_id = m2.id WHERE COALESCE(m2.thread_id, m2.id) = base.thread_id AND (m2.sender_id = #{userId} OR r2.recipient_id = #{userId}) ORDER BY m2.sent_at DESC, m2.id DESC LIMIT 1 ) INNER JOIN mail_recipient last_recipient ON last_recipient.mail_id = last_mail.id INNER JOIN sys_user last_sender ON last_sender.id = last_mail.sender_id INNER JOIN sys_user last_recipient_user ON last_recipient_user.id = last_recipient.recipient_id LEFT JOIN mail_analysis last_analysis ON last_analysis.mail_id = last_mail.id AND last_analysis.recipient_id = last_recipient.recipient_id ORDER BY base.updated_at DESC LIMIT #{size} OFFSET #{offset}
